sys_script_client.script:
function onSubmit() {

    g_form.clearMessages();

    var markFields = {
        internal: 'Internal',
        external: 'External'
    };
    var firstInvalidField = '';

    for (var field in markFields) {
        var value = g_form.getValue(field);

        if (value !== '' && parseFloat(value) < 0) {
            g_form.addErrorMessage(markFields[field] + ' cannot be negative.');
            firstInvalidField = firstInvalidField || field;
        }
    }

    if (firstInvalidField) {
        g_form.getControl(firstInvalidField).focus();
        return false;
    }

    g_form.setValue('total', (parseFloat(g_form.getValue('internal')) || 0) + (parseFloat(g_form.getValue('external')) || 0));

    if (g_form.getValue('published') === 'true' && g_form.getValue('published_on') === '') {
        g_form.setValue('published_on', formatDate(new Date(), g_user_date_time_format));
    }
}
